% each row: type of connection (1 = V||V, 2 = I series I, 3 = V with I), value 1, value 2
c = [1 10 10; 2 5 5; 1 10 5; 2 2 5; 3 5 10];
lbl = 'abcde';
ok = false(1, 5);
for k = 1:5
    ok(k) = c(k,1) == 3 || c(k,2) == c(k,3);
    if ok(k), s = 'valid'; else, s = 'not permissible'; end
    fprintf('(%c) %s\n', lbl(k), s)
end

